package mx.com.mesaregia.seguridad.api.controller;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import mx.com.mesaregia.seguridad.api.request.ConfiguracionUpdateRequest; import mx.com.mesaregia.seguridad.api.response.ConfiguracionResponse; import mx.com.mesaregia.seguridad.application.service.ConfiguracionService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/configuracion") @RequiredArgsConstructor public class ConfiguracionController {private final ConfiguracionService service;@GetMapping @PreAuthorize("hasAuthority('configuracion.consultar')") public List<ConfiguracionResponse> consultar(){return service.consultar();}@GetMapping("/{clave}") @PreAuthorize("hasAuthority('configuracion.consultar')") public ConfiguracionResponse obtener(@PathVariable String clave){return service.obtener(clave);}@PutMapping("/{clave}") @PreAuthorize("hasAuthority('configuracion.modificar')") public ConfiguracionResponse actualizar(@PathVariable String clave,@Valid @RequestBody ConfiguracionUpdateRequest r){return service.actualizar(clave,r);}}
